from pathlib import Path
p=Path.home()/'.config/opencode/instructions/routing.md';p.write_text(p.read_text()+'\nGlobal self-learning execution framework: advisory recall applies to every tool/code workflow; executable templates use tested adapters across domains. A read-only local-host adapter now supplements HA. Registry: ~/.config/opencode/execution-adapters.json. When creating a reusable recurring tool/script, inspect existing procedures first, use typed inputs and JSON outputs, and package a tested adapter when practical. Validate task scope, fresh arguments, relevant code fingerprints and meaningful postconditions before automatic execution. Keep raw unstructured shell/code records advisory. See ~/llm-server/EXECUTION-TEMPLATES.md for the adapter interface and registration/reload steps. Normal cloud/local requests retain streaming and agent fallback.\n')
